function animateMuzzle(actor,g,weapon){const style=muzzleStyles[weapon]||muzzleStyles.rifle,flash=actor.flash,pulse=Math.max(0,Math.min(1,(g.flash||0)/style.duration)),variation=.9+Math.sin((g.muzzlePulse||0)*2.399)*.1;flash.visible=pulse>0&&g.settings?.flashes!==false;const mesh=weapon==='rifle'?actor.rifleMesh:weapon==='shotgun'?actor.shotgunMesh:actor.variants[weapon];mesh?.updateMatrix();flash.position.set(style.tip,weapon==='shotgun'?29:28,weapon==='dualPistols'?(g.dualHand?9:-9):-3);if(mesh)flash.position.applyMatrix4(mesh.matrix);flash.scale.setScalar(1);const {outer,core,petals,halo}=flash.userData;if(!outer)return;const length=style.length*(.7+.3*pulse)*variation,radius=style.radius*(.65+.35*pulse);outer.position.x=length/2;outer.scale.set(radius,length,radius);outer.material.opacity=pulse*.45;core.position.x=length*.22;core.scale.set(radius*.42,length*.44,radius*.42);core.material.opacity=pulse*.92;for(let i=0;i<petals.length;i++){const angle=i*Math.PI/2+(g.muzzlePulse||0)*.71;const mesh=petals[i];mesh.rotation.x=angle;mesh.rotation.z=(i%2?-.12:.12);mesh.position.set(length*.35,Math.cos(angle)*radius*.35,Math.sin(angle)*radius*.35);mesh.scale.set(length*.95,radius*2.2,1);mesh.material.opacity=pulse*.65;}halo.position.x=2;halo.scale.setScalar(radius*4);halo.material.opacity=pulse*.42;}
