const gearPreviews=new WeakMap();
export function drawGearPreview(canvas,profile,time=0,options={}){let preview=gearPreviews.get(canvas);if(!preview){try{const renderer=new T.WebGLRenderer({canvas,antialias:true,alpha:true});renderer.setSize(320,400,false);renderer.setPixelRatio(1);renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.1;const stage=new T.Scene();stage.environment=scene.environment;const lens=new T.OrthographicCamera(-32,32,40,-40,1,500),actor=makeActor(true);scene.remove(actor.root);stage.add(actor.root);stage.add(new T.HemisphereLight('#b5d5cf','#15201b',2));const lamp=new T.DirectionalLight('#dbc69e',3);lamp.position.set(40,80,30);stage.add(lamp);const rim=new T.DirectionalLight('#aacbc1',2.4);rim.position.set(-50,60,-70);stage.add(rim);const ground=new T.Mesh(new T.CircleGeometry(31,48),new T.MeshStandardMaterial({color:'#27352c',roughness:1,transparent:true,opacity:.6}));ground.rotation.x=-Math.PI/2;ground.position.y=.1;stage.add(ground);const contact=new T.Mesh(new T.CircleGeometry(13,32),new T.MeshBasicMaterial({color:'#000000',transparent:true,opacity:.3,depthWrite:false}));contact.rotation.x=-Math.PI/2;contact.position.y=.2;contact.scale.set(1, .65,1);stage.add(contact);lens.position.set(100,48,135);lens.lookAt(4,32,0);preview={renderer,stage,lens,actor,ground,contact,angle:0};gearPreviews.set(canvas,preview);}catch{const context=canvas.getContext('2d');if(context){context.fillStyle='#7c9086';context.fillRect(130,50,60,55);context.fillStyle='#344b44';context.fillRect(110,115,100,120);context.fillStyle='#1f302d';context.fillRect(115,235,35,110);context.fillRect(170,235,35,110);context.fillStyle='#d1bb88';context.font='12px monospace';context.fillText('CONTRACTOR',112,380);}return null;}}const reduced=options.reducedMotion===true,clock=reduced?0:time,selected=options.weapon&&profile.items.some(i=>i.slot===options.weapon)?options.weapon:profile.carried[0],face=Math.sin(clock*.38)*.025;const g={stats:{hasArmor:!!profile.equipped.armor},character:profile.character,p:{x:0,y:0,vx:0,vy:0,face},time:clock,visualTime:clock,weapon:selected,reload:0,pump:0,flash:0,cinematic:true,filmReady:.55,pose:{gait:0,hips:0,head:face+Math.sin(clock*.52)*.045}};preview.angle=damp(preview.angle,options.angle||0,12,options.dt||1/30);preview.actor.root.rotation.y=preview.angle;animateActor(preview.actor,g.p,g,true);const armor=profile.items.find(i=>i.id===profile.equipped.armor);const plate=preview.actor.armorPlate;if(plate){plate.material.color.set({olive:'#94a396',slate:'#8fabb9',sand:'#b7aa8e'}[profile.character?.kit]||['#cad5c6','#b7d3bc','#b2c8cf','#c6b7ce'][armor?.rarity||0]);}if(preview.secondary&&preview.secondaryFamily!==profile.carried.find(id=>id!==selected)){preview.actor.torso.remove(preview.secondary);preview.secondary=null;}if(!preview.secondary&&profile.carried.some(id=>id!==selected&&!['pistol','heavyPistol','dualPistols'].includes(id))){const family=profile.carried.find(id=>id!==selected);preview.secondaryFamily=family;const source=family==='rifle'?preview.actor.rifleMesh:family==='shotgun'?preview.actor.shotgunMesh:preview.actor.variants[family];preview.secondary=new T.Group();const carried=source.clone();carried.visible=true;carried.position.set(-22,-28,3);preview.secondary.add(carried);preview.secondary.position.set(-10,26,8);preview.secondary.rotation.z=1.15;preview.secondary.rotation.y=.25;preview.actor.torso.add(preview.secondary);}preview.renderer.render(preview.stage,preview.lens);return preview;}
export function disposeGearPreview(canvas){const preview=gearPreviews.get(canvas);if(!preview)return;disposeSoldierSkin(preview.actor);for(const m of [preview.ground,preview.contact]){m?.geometry.dispose();m?.material.dispose();}preview.renderer.dispose();preview.renderer.forceContextLoss?.();gearPreviews.delete(canvas);}

export function drawEngineCinematic(ctx,g,frame){filmLens=frame.lens;try{const staged=cinematicActors(g,frame);staged.phase='recover';staged.targetIndex=0;draw(ctx,staged,g.p);}finally{filmLens=null;}}

export function edgeMarker(point,bounds,anchor={x:600,y:380}){if(point.x>=bounds.left&&point.x<=bounds.right&&point.y>=bounds.top&&point.y<=bounds.bottom)return null;return{x:Math.max(bounds.left,Math.min(bounds.right,point.x)),y:Math.max(bounds.top,Math.min(bounds.bottom,point.y)),angle:Math.atan2(point.y-anchor.y,point.x-anchor.x)};}

export function visibleMusicEnemies(g,bounds={left:0,right:1200,top:0,bottom:760}){const visible=new Set();for(const e of g.enemies){const q=project(e.x,32,e.y);if(q.x>=bounds.left-24&&q.x<=bounds.right+24&&q.y>=bounds.top-24&&q.y<=bounds.bottom+24)visible.add(e);}return visible;}
